def post_login_redirect(next_url, site_host, default=DEFAULT_LANDING):
    """Where to send the browser after a successful login.

    `next_url` is the ?next= parameter of the login page. Only targets on this site are
    followed: site-relative paths and absolute https URLs on `site_host`. Anything else
    falls back to `default`.
    """
    if not next_url:
        return default
    # Reject protocol-relative URLs (//host) and paths starting with /\"
    if next_url.startswith("//") or next_url.startswith("/\\"):
        return default
    # For absolute URLs, parse and validate the host matches site_host exactly
    parsed = urlparse(next_url)
    if not parsed.scheme.lower() == "https":
        return default
    if parsed.hostname != site_host:
        return default
    if next_url.startswith("/"):
        return next_url
    return default

